// s 是平台驱动传入的括号字符串；本函数只返回布尔值。
bool isValid(char*s){
    int n=strlen(s),k=0;
    char*st=malloc(n+1);
    // 栈保存尚未配对的左括号，遇到右括号必须关闭最内层。
    for(int i=0;i<n;i++){
        char c=s[i];
        if(c=='('||c=='['||c=='{')st[k++]=c;
        else{
            char want=c==')'?'(':c==']'?'[':'{';
            // 先判断栈非空，再弹出比较；短路判断防止空栈访问。
            if(!k||st[--k]!=want){
                free(st);
                return false;
            }
        }
    }
    free(st);
    // 结束时栈空才表示所有左括号也已经被关闭。
    return k==0;
}

