class Solution {
    // 字符串由平台驱动传入；不要在核心函数里再次读输入。
    public: bool isValid(string s){
        string st;
        // 后打开的左括号必须先关闭，所以只与栈顶配对。
        for(char c:s){
            if(c=='('||c=='['||c=='{')st+=c;
            else{
                char w=c==')'?'(':c==']'?'[':'{';
                // 先检查空栈和类型，不合法时立即返回。
                if(st.empty()||st.back()!=w)return false;
                st.pop_back();
            }
        }
        // 没有剩余左括号时才是完整配对。
        return st.empty();
    }
}
