class Solution {
    // s 是驱动提供的字符串；k 表示模拟栈内的字符数。
    public boolean isValid(String s){
        char[] st=new char[s.length()];
        int k=0;
        // 左括号入栈，右括号只与最后入栈的左括号匹配。
        for(char c:s.toCharArray()){
            if(c=='('||c=='['||c=='{')st[k++]=c;
            else{
                char w=c==')'?'(':c==']'?'[':'{';
                // 先排除空栈，再取栈顶，避免负下标访问。
                if(k==0||st[--k]!=w)return false;
            }
        }
        // 扫描结束后仍有左括号就不能通过。
        return k==0;
    }
}

