class Solution:
    # 接收平台传入的字符串；返回 True/False，由驱动负责输出。
    def isValid(self,s):
        st=[]
        pairs={")":"(","]":"[","}":"{"}
        # 栈的末尾是最近尚未关闭的左括号，符合嵌套顺序。
        for c in s:
            if c in "([{": st.append(c)
            # 先判断空栈，再弹出并与当前右括号所需类型比较。
            elif not st or st.pop()!=pairs[c]: return False
        # 栈必须为空，避免遗漏没有被关闭的左括号。
        return not st

