impl Solution {
    // 接收驱动提供的字符串；只返回布尔值。
    pub fn is_valid(s:String)->bool{
        let mut st=Vec::new();
        // 题目字符都是 ASCII 括号，用字节扫描并维护左括号栈。
        for c in s.bytes(){
            match c{
                b'('|b'['|b'{'=>st.push(c),_=>{
                    let w=match c{
                        b')'=>b'(',b']'=>b'[',_=>b'{'
                    }
                    ;
                    // pop 的 None 表示栈空，Some(w) 表示正确的左括号。
                    if st.pop()!=Some(w){
                        return false;
                    }
                }
            }
        }
        // 返回前检查没有未配对的左括号。
        st.is_empty()
    }
}
